          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P005 supplies the inspection criteria, participant clarification and preservation of the original record."
    }
  },
  "signal_basis": {
    "component_id": "C010.signal_basis",
    "value": "Inspect linked histories for continuity, identity or version conflicts and unexplained transitions, seeking participant clarification while preserving the original record. The relevant observations are internally consistent sequences, with reported offline activity distinguished from logged events, or missing links and contradictions indicating breaks in documented continuity.",
    "scope": "Proposed observations within a bounded cohort of new accounts, assumed to occur for this judgment.",
    "provenance": {
      "refs": [
        {
          "source_id": "P002",
          "role": "CONTEXT"
